// Without loops: tedious repetition
Console.WriteLine("Hello");
Console.WriteLine("Hello");
Console.WriteLine("Hello");

// With a loop: efficient and clear
for (int i = 0; i < 3; i++)
{
    Console.WriteLine("Hello");
}

int count = 1;
while (count <= 5)
{
    Console.WriteLine(count);
    count++;
}

Console.WriteLine("Done!");

// Input validation
string answer = "";
while (answer != "quit")
{
    Console.Write("Enter a command (or quit): ");
    answer = Console.ReadLine() ?? "";
    if (answer != "quit")
    {
        Console.WriteLine($"You entered: {answer}");
    }
}

// Input validation with do...while
int age = 0;
bool valid = false;
do
{
    Console.Write("Enter your age: ");
    valid = int.TryParse(Console.ReadLine() ?? "0", out age);
    if (!valid || age < 0 || age > 150)
    {
        Console.WriteLine("Please enter a valid age.");
        valid = false;
    }
} while (!valid);

Console.WriteLine($"You are {age} years old.");

// Menu system
string choice = "";
do
{
    Console.WriteLine("\n=== Menu ===" );
    Console.WriteLine("1. Start game");
    Console.WriteLine("2. Settings");
    Console.WriteLine("3. Exit");
    Console.Write("Choose: ");
    choice = Console.ReadLine() ?? "";
    if (choice == "1") Console.WriteLine("Starting game...");
    else if (choice == "2") Console.WriteLine("Opening settings...");
} while (choice != "3");

// Count from 1 to 5
for (int i = 1; i <= 5; i++)
{
    Console.WriteLine(i);
}

// Create a pattern
for (int i = 0; i < 5; i++)
{
    for (int j = 0; j <= i; j++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}

// Countdown from 10 to 1
for (int i = 10; i >= 1; i--)
{
    Console.WriteLine(i);
}
Console.WriteLine("Blastoff!");

// Print a 3x3 grid
for (int row = 1; row <= 3; row++)
{
    for (int col = 1; col <= 3; col++)
    {
        Console.Write("* ");
    }
    Console.WriteLine();
}

// Multiplication table
for (int i = 1; i <= 3; i++)
{
    for (int j = 1; j <= 3; j++)
    {
        Console.Write((i * j) + " ");
    }
    Console.WriteLine();
}

// Pyramid pattern
for (int row = 1; row <= 5; row++)
{
    for (int space = 1; space <= 5 - row; space++)
    {
        Console.Write(" ");
    }
    for (int star = 1; star <= row; star++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}

// Process each name
string[] names = { "Alice", "Bob", "Charlie" };
foreach (string name in names)
{
    Console.WriteLine(name);
}

// Process each score
int[] scores = { 95, 87, 92, 88 };
int total = 0;
foreach (int score in scores)
{
    total += score;
    Console.WriteLine(score);
}
Console.WriteLine($"Total: {total}");

// Simple display
string[] colours = { "red", "blue", "green" };
foreach (string colour in colours)
{
    Console.WriteLine($"Colour: {colour}");
}

// Break: search for a value
int[] numbers = { 10, 20, 30, 40, 50 };
int target = 30;
bool found = false;
foreach (int num in numbers)
{
    if (num == target)
    {
        found = true;
        break;
    }
}
Console.WriteLine(found ? "Found!" : "Not found.");

// Continue: skip invalid values
int[] scores = { 95, -5, 87, 110, 92 };
int sum = 0;
int count = 0;
foreach (int score in scores)
{
    if (score < 0 || score > 100)
    {
        continue;
    }
    sum += score;
    count++;
}
Console.WriteLine($"Average: {sum / count}");

// Menu exit with break
string choice = "";
while (choice != "exit")
{
    Console.Write("Enter command: ");
    choice = Console.ReadLine() ?? "";
    if (choice == "quit") break;
    Console.WriteLine($"You entered: {choice}");
}

using System;

Random random = new Random();
bool playAgain = true;

while (playAgain)
{
    int secret = random.Next(1, 101);
    int attempts = 0;
    int guess = 0;
    bool correct = false;

    Console.WriteLine("\n=== Number Guessing Game ===" );
    Console.WriteLine("Guess the number between 1 and 100!");

    while (!correct)
    {
        Console.Write("Your guess: ");
        if (int.TryParse(Console.ReadLine() ?? "0", out guess))
        {
            if (guess < 1 || guess > 100)
            {
                Console.WriteLine("Please guess between 1 and 100.");
                continue;
            }

            attempts++;

            if (guess == secret)
            {
                Console.WriteLine($"Correct! You won in {attempts} attempts!");
                correct = true;
            }
            else if (guess < secret)
            {
                Console.WriteLine("Too low. Try higher.");
            }
            else
            {
                Console.WriteLine("Too high. Try lower.");
            }
        }
        else
        {
            Console.WriteLine("Please enter a valid number.");
        }
    }

    Console.Write("Play again? (yes/no): ");
    string response = Console.ReadLine()?.ToLower() ?? "no";
    playAgain = response == "yes" || response == "y";
}

Console.WriteLine("Thanks for playing!");
